/* Monitor del sistema */
#include "z.h"
static zwin *W; static zproc P[64], Q[64]; static int n, nq, sel = -1; static u8 hist[120]; static int hp; static u64 last;
static void sample(void) { zsys s; z_sysinfo(&s); memcpy(Q, P, sizeof P); nq = n; n = z_procs(P, 64); u64 t = z_ms(), dt = t - last; last = t; u64 use = 0; for (int i = 0; i < n; i++) for (int j = 0; j < nq; j++) if (P[i].pid == Q[j].pid && P[i].cpu >= Q[j].cpu) use += P[i].cpu - Q[j].cpu; hist[hp++ % 120] = dt ? MIN(100, use * 100 / dt) : 0; }
static void draw(void) {
    zsys s; z_sysinfo(&s); g_clear(W, UI_WHITE); char b[160]; g_textb(W, 12, 8, s.cpu, UI_TEXT); u64 used = s.mem_total - s.mem_free; snprintf(b, 160, _("Memoria: %lu de %lu MB   Procesos: %d   Activo: %lu s   %s"), used >> 20, s.mem_total >> 20, n, s.uptime_ms / 1000, s.boot_mode == 2 ? "UEFI" : "BIOS"); g_text(W, 12, 28, b, UI_MUTED);
    int gw = W->w - 24; g_rect(W, 12, 50, gw, 14, UI_PANEL); g_rect(W, 12, 50, gw * (used >> 12) / MAX(1, s.mem_total >> 12), 14, UI_ACC); g_rect(W, 12, 70, gw, 60, 0x0F172A); for (int i = 0; i < 120; i++) { int v = hist[(hp + i) % 120], h = v * 58 / 100, x = 12 + i * gw / 120; g_rect(W, x, 129 - h, gw / 120 + 1, h, 0x14B8A6); } g_text(W, 18, 74, "CPU", 0x5EEAD4);
    g_rect(W, 0, 138, W->w, 20, UI_PANEL); g_text(W, 12, 140, "PID", UI_TEXT); g_text(W, 60, 140, "Proceso", UI_TEXT); g_text(W, 260, 140, "Hilos", UI_TEXT); g_text(W, 320, 140, "Memoria", UI_TEXT); g_text(W, 420, 140, "CPU (s)", UI_TEXT);
    for (int i = 0; i < n; i++) { int y = 160 + i * 20; if (y + 20 > W->h - 36) break; if (P[i].pid == sel) g_rect(W, 0, y, W->w, 20, UI_ACC2); snprintf(b, 20, "%d", P[i].pid); g_text(W, 12, y + 2, b, UI_TEXT); g_text(W, 60, y + 2, P[i].name, UI_TEXT); snprintf(b, 20, "%d", P[i].threads); g_text(W, 260, y + 2, b, UI_TEXT); snprintf(b, 20, "%lu KB", P[i].mem_kb); g_text(W, 320, y + 2, b, UI_TEXT); snprintf(b, 20, "%lu", P[i].cpu / 1000); g_text(W, 420, y + 2, b, UI_TEXT); }
    ui_button(W, W->w - 150, W->h - 32, 140, 26, "Terminar proceso", sel >= 0 ? 2 : 0); ui_button(W, W->w - 260, W->h - 32, 100, 26, "Imprimir", 0); zw_present(W);
}
static void print_(void) { zsys s; z_sysinfo(&s); sb_t b = {0}; u64 used = s.mem_total - s.mem_free; sb_f(&b, "%s\n%s: %lu / %lu MB\n%s: %lu s\n\n%-6s %-24s %6s %10s %9s\n", s.cpu, _("Memoria"), used >> 20, s.mem_total >> 20, _("Activo"), s.uptime_ms / 1000, "PID", _("Proceso"), _("Hilos"), _("Memoria"), "CPU (s)");
    for (int i = 0; i < n; i++) sb_f(&b, "%-6d %-24s %6d %7lu KB %9lu\n", P[i].pid, P[i].name, P[i].threads, P[i].mem_kb, P[i].cpu / 1000); zp_print_text("Monitor del sistema", 0, b.p, 1); free(b.p); }
int main(const char *a) { W = zw_new("Monitor del sistema", -1, 0, 540, 460, WF_DECOR | WF_RESIZE); last = z_ms(); sample(); draw(); zevent e; u64 t = z_ms();
    for (;;) { int g = z_event(&e, 500); if (g && e.type == EV_REDRAW) { draw(); continue; } if (g && e.win == (u32)W->id) { if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) zw_resized(W, e.x, e.y); else if (e.type == EV_KEY && e.ch == 16) print_(); else if (e.type == EV_DOWN && e.y >= W->h - 36 && e.x >= W->w - 260 && e.x < W->w - 160) print_(); else if (e.type == EV_DOWN) { if (e.y >= W->h - 36 && e.x >= W->w - 150) { if (sel >= 0) { z_kill(sel); sel = -1; } } else if (e.y >= 160) { int i = (e.y - 160) / 20; sel = i < n ? P[i].pid : -1; } } else continue; draw(); } if (z_ms() - t >= 900) { t = z_ms(); sample(); draw(); } }
}
